-- ════════════════════════════════════════════════════════
-- 225 — le journal ne coupe plus
-- ────────────────────────────────────────────────────────
-- QUATRIEME COLONNE QUI COUPAIT SANS LE DIRE — et la sonde generale
-- qui l'a trouvee entre maintenant dans tests/run.php. `moderation_log.
-- detail` est un varchar(255), `action` un varchar(40), et le serveur
-- n'est pas en mode strict : 188 entrees de journal (migrations 153 a
-- 210) s'arretent au 255e caractere ; 8 actions font 40 pile, entieres
-- mais sans marge. Les controles
-- « journal_non_tronque » n'existent que depuis la 214 ; avant, rien
-- ne regardait.
--
-- Les textes entiers sont dans les migrations qui les ont ecrits. On
-- elargit (`detail` TEXT, `action` varchar(100)), puis on reecrit
-- chaque entree coupee, reconnue par son acteur, son action et le
-- prefixe exact de son detail — jamais par un id, qui differe d'une
-- base a l'autre.
-- ════════════════════════════════════════════════════════

ALTER TABLE `moderation_log`
  MODIFY `action` VARCHAR(100) NOT NULL,
  MODIFY `detail` TEXT NULL;

