UPDATE `moderation_log` SET `action` = 'lounges_retires', `detail` = '25 villes sans LCDH : France (Specialist a Lyon et Toulouse), Japon (Tokyo), Chine (Pekin), Canada (Montreal, Toronto), Israel (Rishon LeZion, Haifa), Turquie (duty free Istanbul), Autriche, Croatie, Philippines, Ghana, Kenya, Ukraine, Egypte (autres echelons), Indonesie, Venezuela, Guatemala, Honduras, Paraguay, Coree du Sud (aucune entree)'
 WHERE `acteur_nom` = 'migration 153' AND `action` = 'lounges_retires' AND LEFT(`detail`, 80) = '25 villes sans LCDH : France (Specialist a Lyon et Toulouse), Japon (Tokyo), Chi' AND CHAR_LENGTH(`detail`) = 255;
