DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 225';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 225','systeme','journal_elargi_et_reecrit','systeme',0,
   'moderation_log.detail passe de varchar(255) a TEXT, action de varchar(40) a varchar(100). 188 entrees coupees depuis la 153 reecrites entieres depuis les migrations. Quatrieme colonne trouvee par la meme sonde, qui entre dans tests/run.php');

SELECT
  (SELECT DATA_TYPE FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'moderation_log' AND COLUMN_NAME = 'detail') = 'text' AS detail_text,
  (SELECT CHARACTER_MAXIMUM_LENGTH FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'moderation_log' AND COLUMN_NAME = 'action') = 100 AS action_100,
  -- Une entree de la 161 (fait_corrige, Aladino) fait exactement 255
  -- caracteres dans la migration : entiere, c'est l'exception nommee.
  (SELECT COUNT(*) FROM `moderation_log` WHERE CHAR_LENGTH(`detail`) = 255
     AND NOT (`acteur_nom` = 'migration 161' AND `action` = 'fait_corrige')) = 0 AS plus_rien_a_255,
  -- Pas de compte exact : une migration passee deux fois a laisse des
  -- doublons, et les entrees des 168 et 177 manquent en base locale.
  -- Le vrai controle est plus_rien_a_255 ; celui-ci dit que l'ALTER a
  -- bien laisse passer du long.
  (SELECT COUNT(*) FROM `moderation_log` WHERE CHAR_LENGTH(`detail`) > 255) > 0 AS des_entrees_entieres;
